<?php namespace App\Http\Resources; use Illuminate\Http\Request; use Illuminate\Http\Resources\Json\JsonResource; class BookingResource extends JsonResource {public function toArray(Request $r):array{return ['id'=>$this->id,'event_id'=>$this->event_id,'status'=>$this->status->value,'total'=>$this->total,'expires_at'=>$this->expires_at,'paid_at'=>$this->paid_at,'items'=>$this->whenLoaded('items',fn()=>$this->items->map(fn($i)=>['category_id'=>$i->ticket_category_id,'quantity'=>$i->quantity,'unit_price'=>$i->unit_price])),'tickets'=>$this->whenLoaded('tickets',fn()=>$this->tickets->map(fn($t)=>['code'=>$t->code,'qr_payload'=>$t->qr_payload,'issued_at'=>$t->issued_at]))];}}
